using System;namespace Recovered.Gameplay {public static class PtlProgramSlots {static bool Find(SoundSetupImage m,uint manager,out int index){unchecked{int cursor=(int)m.Word(manager+0x79184);index=cursor+1;if(index<400){for(;index<400;index++)if((int)m.Word(manager+(uint)index*0x4d8+8)<=0)return true;}index=0;if(cursor>0){for(;index<cursor;index++)if((int)m.Word(manager+(uint)index*0x4d8+8)<=0)return true;}return false;}}public static void Clear(SoundSetupImage m,uint program,Func<SoundSetupImage,uint,uint[],uint> call){unchecked{uint resource=m.Word(program+0x4cc);if(resource!=0){uint target=m.Word(m.Word(resource)+8);call(m,target,new uint[]{resource});m.Word(program+0x4cc,0);}resource=m.Word(program+0x4d0);if(resource!=0){uint target=m.Word(m.Word(resource)+8);call(m,target,new uint[]{resource});m.Word(program+0x4d0,0);}Reset(m,program,call);}}public static uint Reset(SoundSetupImage m,uint program,Func<SoundSetupImage,uint,uint[],uint> call){return ResetBody(m,program);}public static uint ResetBody(SoundSetupImage m,uint program){m.Word(program,0xffffffff);return program;}public static uint Select(SoundSetupImage m,uint manager,uint output,Func<SoundSetupImage,uint,uint[],uint> call){unchecked{int index;if(!Find(m,manager,out index))return 0;uint program=manager+(uint)index*0x4d8+4;m.Word(manager+0x79184,(uint)index);Clear(m,program,call);m.Word(output,(uint)index);return program;}}public static uint[] Values(SoundSetupImage m,uint manager,Func<SoundSetupImage,uint,uint[],uint> call){unchecked{int index;if(!Find(m,manager,out index))return new uint[]{0,0};uint program=manager+(uint)index*0x4d8+4;m.Word(manager+0x79184,(uint)index);Clear(m,program,call);return new uint[]{program,(uint)index};}}}}
